    "m.du.liveH": "Live TV",
    "m.du.liveIntro": "Open <strong>Live TV</strong> in the left menu. You get a program guide (EPG) with a live preview. Press OK on the current programme to watch fullscreen — the picture continues without reconnecting.",
    "m.du.liveAlt": "Live TV EPG",
    "m.du.liveCap": "Live TV guide — channels, timeline, and live preview.",
    "m.du.liveGuideH": "Guide and folders",
    "m.du.live1": "The left sidebar lists your selected TV folders (per provider).",
    "m.du.live2": "Favorite Channels sits at the top once you star channels or move folders under favorites.",
    "m.du.live3": "Search the guide from the side menu to find a programme or channel.",
    "m.du.live4": "If your provider supports catch-up, you can start a past programme from the guide.",
    "m.du.liveFavFolderH": "Favorites, favorite folders, and hiding normal TV folders",
    "m.du.liveFav1": "<strong>Add a channel:</strong> hold <strong>OK</strong> on a channel in the guide and choose <strong>Add to favorites</strong>.",
    "m.du.liveFav2": "<strong>Add or move a whole folder:</strong> hold <strong>OK</strong> on a folder in the sidebar to choose <strong>Add all channels to Favorite Channels</strong> or <strong>Move folder under favorites</strong> so it becomes a favorite folder.",
    "m.du.liveFavGroup": "<strong>Channel groups inside Favorites:</strong> hold <strong>OK</strong> on a channel inside Favorite Channels and choose <strong>Add channel group above</strong> to create sections, or <strong>Move channel or groups</strong> to reorder them.",
    "m.du.liveFavHide": "<strong>Hide normal TV folders:</strong> go to <strong>Settings → Playback &amp; Live TV → Live TV &amp; EPG → Favorites → EPG sidebar</strong> and switch from <em>All TV folders</em> to <em>Favorite Channels</em>. Normal provider folders are hidden so only your favorites and favorite folders appear, and Live TV opens directly into your favorites.",
    "m.du.liveFav4": "Set or remove a reminder on a programme. How many minutes before start is under Settings → Playback &amp; Live TV → Live TV &amp; EPG → EPG &amp; Program Guide.",
    "m.du.liveFavAlt": "Live TV favorites",
    "m.du.liveFavSetAlt": "Favorites settings and EPG sidebar filter",
    "m.du.liveFavSetCap": "Settings → Playback &amp; Live TV → Live TV &amp; EPG → Favorites — hide normal TV folders with EPG sidebar.",
    "m.du.liveFavH": "Backup streams for favorite channels",
    "m.du.liveMultiP": "A favorite is not limited to one provider. You can attach extra backup streams from other providers onto the same Favorite Channel. If one source is busy or drops, another stream is already linked.",
    "m.du.liveMultiLong": "<strong>From the long-press menu (hold OK):</strong> hold <strong>OK</strong> on any channel in a normal folder and choose <strong>Use as backup for a favorite</strong> to attach it directly — or hold <strong>OK</strong> on any channel and choose <strong>Find backup streams for favorites</strong>. On a favorite that already has backups, choose <strong>See all streams</strong> to inspect or remove them.",
    "m.du.liveMulti1": "<strong>From Settings:</strong> open <strong>Settings → Playback &amp; Live TV → Live TV &amp; EPG → Favorites → Find backup streams for favorites</strong>. You can also run <strong>Scan favorites</strong> (Missing or All) there to test video and audio quality across linked streams.",
    "m.du.liveMulti2": "The player menu (OK in fullscreen) lets you switch streams by hand if several are linked.",
    "m.du.liveLongAlt": "Live TV long-press menu",
    "m.du.liveLongCap": "Long-press menu (hold OK on a channel) — favorites, backup streams, Change EPG, and Change icon.",
    "m.du.liveLinkAlt": "Find backup streams for favorites",
    "m.du.liveLinkCap": "Find backup streams for favorites — match and attach backup streams from other providers.",
    "m.du.liveMultiNote": "Linked backups are what <a href=\"daily-switching.html\">Intelligent stream switching</a> uses when a stream fails.",
    "m.du.epgMgrH": "EPG Manager (EPG &amp; Program Guide)",
    "m.du.epgMgrP": "Open <strong>Settings → Playback &amp; Live TV → Live TV &amp; EPG → EPG &amp; Program Guide</strong> to manage your TV guide sources and channel matching.",
    "m.du.epgMgr1": "<strong>Add your own EPG list:</strong> choose <strong>External EPG &amp; Refresh</strong> (also reachable via <strong>+ Manage XMLTV</strong> on IPTV Providers) to see provider EPG status, force a refresh of all guides now, or add up to <strong>3 custom XMLTV URLs</strong> (typed or scanned via QR from your phone). Custom lists are shared across the household.",
    "m.du.epgMgr2": "<strong>Auto-match channels to the best available EPG:</strong> open <strong>EPG Channel Matcher</strong> and press <strong>Auto-match Wizard</strong>. SmartStream scans all your provider EPGs and custom XMLTV lists and matches each channel to the best available guide. You can filter by <em>All</em>, <em>Suggested</em>, or <em>Unmatched</em>, switch folder (e.g. Favorite Channels), or search manually.",
    "m.du.epgMgr3": "<strong>Single channel in the guide:</strong> you can also hold <strong>OK</strong> on any channel in Live TV and choose <strong>Change EPG</strong> to pick or reset the guide for that channel alone.",
    "m.du.epgMgrAlt": "EPG & Program Guide settings",
    "m.du.epgMgrCap": "EPG &amp; Program Guide — days forward/back, reminders, EPG Channel Matcher, and External EPG &amp; Refresh.",
    "m.du.epgMatchAlt": "EPG Channel Matcher",
    "m.du.epgMatchCap": "EPG Channel Matcher — Auto-match Wizard, filters, and recommended EPG matches across sources.",
    "m.du.iconH": "TV channel icons",
    "m.du.icon1": "<strong>From the long-press menu (hold OK):</strong> hold <strong>OK</strong> on a channel in the Live TV guide and choose <strong>Change icon</strong>. You can pick logos from the stream, EPG, or the built-in logo catalog (with pixel resolution shown), or choose <strong>Reset to original</strong>.",
    "m.du.icon2": "<strong>Auto-match from Settings:</strong> open <strong>Settings → Playback &amp; Live TV → Live TV &amp; EPG → Channel Icon Matcher</strong> and press <strong>Auto-match</strong> to automatically find and apply the best channel logos for all channels in the selected folder. You can also filter <em>Custom</em> vs <em>Original</em>, search all logos manually, or reset channels back to their original stream logo.",
    "m.du.iconDlgAlt": "Change channel icon dialog",
    "m.du.iconDlgCap": "Change icon from the long-press menu — choose from Stream, EPG, or Custom logos.",
    "m.du.iconMgrAlt": "Channel Icon Matcher",
