    "m.du.navSwitch": "Intelligent stream switching",
    "m.du.homeH": "HOME",
    "m.du.homeP": "Home er det første punkt i venstre menu. Her ser du, hvad du var i gang med, hvad appen foreslår, og titler du har gemt.",
    "m.du.homeP2": "Brug venstre menu til Live TV, Movies eller Series. Settings ligger nederst i samme menu.",
    "m.du.homeAlt": "HOME",
