    "m.du.searchAlt": "AI-søgning",
    "m.du.switchTitle": "Daglig brug — Intelligent stream switching — SmartStream",
    "m.du.switchPageH": "3. Daglig brug — Intelligent stream switching",
    "m.du.switchLead": "Intelligent Switching mellem udbydere: Når afspilning fejler, eller en anden enhed tager pladsen, skifter SmartStream automatisk. Det gør ingen anden IPTV-app.",
    "m.du.switchWhatH": "Hvad det gør",
    "m.du.switchP": "De fleste IPTV-apps stopper, når en stream fejler, eller når et andet TV i huset bruger samme login-plads. SmartStream finder en anden stream, du allerede har linket — fra en anden udbyder om nødvendigt — og fortsætter afspilningen.",
    "m.du.switchLi1": "<strong>Live TV:</strong> backup-streams på en Favorite Channel.",
    "m.du.switchLi2": "<strong>Film og serier:</strong> en anden kopi af samme titel fra en anden udbyder.",
    "m.du.switchLi3": "<strong>Optaget plads:</strong> hvis en anden enhed bruger en udbyder, kan SmartStream bede det TV om at frigive, og skifte.",
    "m.du.switchHowH": "Sådan sætter du det op",
