    "m.pr.liveP": "På ekstra profiler kan du slå <strong>Primary TV setup</strong> til. Så bruger profilen de samme TV-mapper, favoritter, kanalrækkefølge og guide-koblinger som den første profil. Slå fra for at vælge mapper selv.",
