    "m.st.accountAlt": "Accounts & Connections",
    "m.st.account1": "<strong>IPTV Providers</strong> — tilføj op til 5 Xtream-konti (QR fra telefon eller skriv på TV). Per udbyder: Test, Save, Select Movies and Series, Select TV Channels, max connections, og slå afspilning til/fra for denne profil.",
    "m.st.accountXmltv": "<strong>+ Manage XMLTV</strong> (på provider-skærmen) — EPG-kildestatus, opdater alle guides nu, og op til 3 brugerdefinerede XMLTV-lister for hele husstanden.",
