    "m.st.pn1": "<strong>Network Buffer Size</strong> — Small til Extra Large. Større er mere stabilt på langsomt net; mindre starter hurtigere.",
    "m.st.pn2": "<strong>Auto-switch poor encodes</strong> — skjuler 4K H.264-filmstreams i Details (de hakker ofte). Dolby Vision og HEVC/H.265 påvirkes ikke. Skifter også automatisk 30 fps telecine-encodes.",
    "m.st.pn3": "<strong>Intelligent Switching</strong> — prøv automatisk en anden stream, når afspilning fejler.",
    "m.st.pn4": "<strong>Preferred stream quality</strong> — lægger din valgte kvalitet først i long-press Play-listen (f.eks. 4K UHD).",
    "m.st.liveH": "Live TV & EPG",
    "m.st.liveAlt": "Live TV & EPG",
    "m.st.live1": "<strong>Autoplay last channel</strong> — ved app-start åbnes Live TV på sidst sete kanal.",
    "m.st.live2": "<strong>EPG &amp; Programguide</strong> — EPG-dage frem/tilbage, påmindelsestid, <strong>EPG-kanalmatcher</strong> (auto-match kanaler til bedste XMLTV-kilde) og <strong>Eksterne EPG-kilder &amp; Genindlæsning</strong> (tilføj op til 3 egne XMLTV-lister og gennemtving opdatering).",
    "m.st.liveIcon": "<strong>Kanalikon Matcher</strong> — auto-match, søg eller tilpas kanallogoer til dine mapper.",
    "m.st.liveFavH": "Favorites",
    "m.st.live3": "Åbner ekstra Live TV-valg:",
    "m.st.live3a": "<strong>EPG-sidepanel</strong> — Alle TV-mapper eller Favoritkanaler (skjuler normale udbyder-mapper og åbner direkte i favoritter).",
    "m.st.live3b": "<strong>Auto clean channel names in favorites</strong> — fjerner præfiks/suffiks fra favoritnavne.",
    "m.st.live3c": "<strong>Find reserve-streams til favoritter</strong> — find og tilføj reserve-streams på andre udbydere til favoritkanaler.",
    "m.st.live3d": "<strong>Scan favorites</strong> — Missing eller All: find video-/lydkvalitet for favoritter med flere streams.",
    "m.st.audioH": "Audio",
    "m.st.audio1": "<strong>Preferred language</strong> — første lydspor, når det findes.",
    "m.st.audio2": "<strong>Fallback language</strong> — bruges hvis det foretrukne spor mangler.",
    "m.st.audio3": "<strong>HDMI Passthrough (Bitstream)</strong> — send Dolby/DTS uændret til dit lydsystem.",
    "m.st.langH": "UI & Languages",
    "m.st.langAlt": "UI & Languages",
    "m.st.subH": "Subtitles",
    "m.st.sub1": "<strong>Configure OpenSubtitles</strong> — valgfri konto til undertekster fra nettet.",
    "m.st.sub2": "<strong>Preferred subtitle language</strong> — standardsprog, fallback og Prioritize SDH subtitles (for hørehæmmede).",
    "m.st.sub3": "<strong>Subtitle Appearance</strong> — skrifttype, størrelse, farve og placering.",
    "m.st.subAppAlt": "Undertekst-udseende",
    "m.st.osAlt": "OpenSubtitles",
    "m.st.osAutoH": "OpenSubtitles: automatisk oversættelse og synkronisering",
    "m.st.osAutoP": "Ingen undertekster på dit sprog? SmartStream kan finde en fil på et andet sprog og oversætte den for dig. Undertekster, der kommer for tidligt eller for sent, rettes automatisk til filmen.",
    "m.st.osTrH": "Sådan slår du automatisk oversættelse til",
    "m.st.osTr1": "<strong>Indstillinger → UI &amp; Languages → Undertekster → Configure OpenSubtitles</strong>, og log ind med din OpenSubtitles-konto (en Pro-funktion).",
    "m.st.osTr2": "<strong>Foretrukket undertekstsprog</strong>: vælg det sprog, du vil læse. Automatisk oversættelse kører ikke, hvis det står på Ingen eller engelsk.",
    "m.st.osTr3": "Tilføj din egen Gemini-nøgle under <strong>Indstillinger → AI</strong> (en gratis nøgle fra Google AI Studio). Oversættelsen bruger din nøgle.",
    "m.st.osTr4": "Tilbage på OpenSubtitles-siden sætter du <strong>Translate OpenSubtitles</strong> til <strong>Enabled</strong>. Den er slået fra som standard og gælder pr. profil.",
    "m.st.osUseH": "Mens du ser",
    "m.st.osUse1": "Start en film eller en episode fra siden med detaljer. Har hverken streamen eller OpenSubtitles dit sprog, vælger SmartStream en engelsk fil (eller en fil på et andet sprog, hvis der ingen engelsk er) og oversætter den.",
    "m.st.osUse2": "Et hjul vises kort. Filmen starter, så snart den første del er oversat, og resten oversættes, mens du ser.",
    "m.st.osUse3": "Den oversatte fil gemmes, så næste gang starter den med det samme. Det virker også ved cast og fra Fortsæt med at se.",
    "m.st.osUse4": "Vil du vælge en fil selv, så tryk OK i afspilleren, derefter <strong>Subs → OpenSubs</strong>, og søg på et hvilket som helst sprog. Er indstillingen slået til, oversættes filer på andre sprog automatisk; er den slået fra, sætter du flueben i <strong>Oversæt andre sprog til …</strong>.",
    "m.st.osUse5": "Infolinjen i OK-menuen viser den aktive fil, fx <em>Danish (Opensubs, oversat)</em>.",
    "m.st.osSyncH": "Automatisk synkronisering",
    "m.st.osSync1": "Når en OpenSubtitles-fil er i brug, tjekker SmartStream tidspunkterne i baggrunden. Har filmen sit eget undertekstspor, sammenligner den, hvornår teksten kommer; ellers lytter den efter, hvornår der tales.",
    "m.st.osSync2": "Underteksterne vises som normalt. Er de ude af takt, hopper teksten på plads, som regel inden for et minut, og finjusteres de næste par minutter. En film med en lang intro med musik kan tage lidt længere tid.",
    "m.st.osSync3": "Rettelsen gemmes pr. undertekstfil og følger dine andre enheder via Cloud Sync, så du kun venter første gang.",
    "m.st.osSync4": "Du kan altid justere selv med knapperne <strong>Sub delay − / +</strong> i OK-menuen. Kan appen ikke finde tidspunktet, minder en kort tekst dig om det.",
    "m.st.osNote": "Oversættelse kræver en Gemini-nøgle. En gratis nøgle har en daglig grænse; er den nået, ser du originalteksten, og resten oversættes næste gang.",
    "m.st.osdH": "Interface & OSD",
    "m.st.osd1": "<strong>Playback bar auto-hide delay</strong> — hvor længe kontrolbaren vises (eller Off).",
    "m.st.osd2": "<strong>Show Grid Overlay</strong> — gitter på skærmen under browse.",
    "m.st.osd3": "<strong>AI voice search</strong> — vis mikrofonen i søgning til naturlige forespørgsler (kræver Gemini).",
    "m.st.metaH": "Languages & Metadata",
    "m.st.meta1": "<strong>UI Translation</strong> — appsprog.",
    "m.st.meta2": "<strong>Metadata Language (TMDB)</strong> — sprog til titler og beskrivelser fra TMDB (primary profil).",
    "m.st.sysH": "Profile & System",
    "m.st.sysAlt": "Profile & System",
    "m.st.sys1": "<strong>Parental Control PIN</strong> — opret, skift eller fjern PIN, der låser udvalgt indhold og mapper (skjult på børneprofiler).",
    "m.st.sys2": "<strong>Profile Ratings</strong> — se eller fjern 👍 / 👎 for denne profil.",
    "m.st.sys3": "<strong>Diagnostics & Troubleshooting</strong> — system- og udbyderstatus, performance overlay og <strong>Send logs via QR</strong> til support.",
    "m.st.ratingsAlt": "Profil-ratings",
