    "m.ix.figAlt": "HOME dashboard",
    "m.ix.figCap": "HOME — Weiterschauen, Vorschläge und Meine Liste.",
    "m.ix.whatH": "Was ist SmartStream?",
    "m.ix.whatP": "Eine Android-TV- und Fire-TV-App, die dein eigenes IPTV-Konto zur Wohnzimmererfahrung macht: Filme und Serien mit Postern, Live-TV mit Programmführer, Weiterschauen, Haushaltsprofile und optionale KI-Suche. Favoritenkanäle können Backup-Streams anderer Anbieter tragen, und Intelligent Switching wechselt automatisch, wenn ein Stream ausfällt — das macht keine andere IPTV-App. Du brauchst einen eigenen IPTV-Anbieter — SmartStream verkauft keine Inhalte.",
    "m.ix.remoteH": "Fernbedienung",
    "m.ix.remote1": "<strong>D-Pad</strong> — Fokus bewegen",
    "m.ix.remote2": "<strong>OK</strong> — auswählen",
    "m.ix.remote3": "<strong>Zurück</strong> — einen Schritt zurück (beendet die App nicht von Home)",
    "m.ix.remote4": "<strong>OK gedrückt halten</strong> auf einer Karte — Bewertung (👍/👎)",
    "m.ix.remote4b": "<strong>Hold OK</strong> on a Live TV channel or folder — favorites, backup streams, Change EPG, Change icon",
    "m.ix.remote5": "<strong>Live-TV Vollbild:</strong> Hoch/Runter zappt Sender, Links öffnet den Guide, Rechts springt zum vorherigen Sender",
    "m.ix.pagerHome": "← Produktseite",
    "m.ix.pagerNext": "Weiter: Erste Schritte →",
    "m.gs.title": "Getting started — SmartStream",
    "m.gs.h1": "1. Erste Schritte",
    "m.gs.lead": "Die App in einer Minute.",
    "m.gs.needH": "Du brauchst",
    "m.gs.need1": "Android TV, Google TV oder Fire TV mit Fernbedienung",
    "m.gs.need2": "IPTV account (Xtream URL + username + password)",
    "m.gs.need3": "Internet connection",
    "m.gs.stepsH": "Sechs Schritte",
    "m.gs.step1": "Start the app → choose or create a profile",
    "m.gs.step2": "Add an IPTV source under Settings → Accounts & Connections → IPTV Providers",
    "m.gs.step3": "Select which movie and series folders to import",
    "m.gs.step4": "Select which Live TV channel folders to import",
    "m.gs.step5": "Wait for the library scan (first time takes a while)",
    "m.gs.step6": "Use <strong>Home</strong>, <strong>Movies</strong>, <strong>Series</strong> and <strong>Live TV</strong> in the left menu",
    "m.gs.figAlt": "Sidebar",
    "m.gs.figCap": "Linkes Menü: Home, Filme, Serien, Live-TV, Einstellungen.",
    "m.gs.note": "SmartStream verkauft kein IPTV. Dein Anbieter liefert URL und Login.",
    "m.gs.pagerPrev": "← Contents",
    "m.gs.pagerNext": "Next: First-time setup →",
    "m.fs.title": "First-time setup — SmartStream",
    "m.fs.h1": "2. Ersteinrichtung",
    "m.fs.newH": "New TV or fresh install",
    "m.fs.newP": "The app typically guides you in this order:",
    "m.fs.new1": "App language",
    "m.fs.new2": "New device or restore from cloud",
    "m.fs.new3": "Create profile (name, avatar, optional kids profile)",
    "m.fs.new4": "Cloud Sync — can be skipped",
    "m.fs.new5": "Gemini API — can be skipped",
    "m.fs.new6": "Metadata language (TMDB)",
    "m.fs.new7": "Add IPTV source",
