    "m.pr.up5_3": "Browse filters for Movies and Series",
    "m.pr.up5_4": "Movie and series folder selection per IPTV source (if configured)",
    "m.pr.up5_5": "Live TV folders, favorites, and guide — or share the primary profile’s TV setup",
    "m.pr.kidsH": "Kids profile",
    "m.pr.kidsP": "Enable <strong>Kids profile</strong> when creating it. Locked content and PIN prompts are hidden.",
    "m.pr.kidsAlt": "Kids profile",
    "m.pr.pinH": "Parental Control PIN",
    "m.pr.pinP": "Settings → Profile & System → Parental Control PIN. You can lock selected content and Live TV folders so they require the PIN.",
    "m.pr.liveH": "Live TV per profile",
    "m.pr.liveP": "On extra profiles you can turn on <strong>Primary TV setup</strong>. Then that profile uses the same TV folders, favorites, channel order, and guide mappings as the first profile. Turn it off to pick folders independently.",
    "m.pr.primaryH": "Primary profile",
    "m.pr.primaryP": "The first profile controls Cloud Sync, Gemini and TMDB settings. It cannot be deleted.",
