    "m.ix.figCap": "INICIO — Seguir viendo, sugerencias y Mi lista.",
    "m.ix.whatH": "¿Qué es SmartStream?",
    "m.ix.whatP": "Una app de Android TV y Fire TV que convierte tu cuenta IPTV en una experiencia de salón: películas y series con pósters, TV en vivo con guía, Seguir viendo, perfiles del hogar y búsqueda IA opcional. Los canales favoritos pueden llevar streams de respaldo de otros proveedores, e Intelligent Switching cambia automáticamente cuando un stream falla — ninguna otra app IPTV lo hace. Necesitas tu propio proveedor IPTV — SmartStream no vende contenido.",
