    "m.fs.iptvP": "<strong>Settings → Accounts &amp; Connections → IPTV Providers</strong>",
    "m.fs.iptvP2": "You can type the server URL, username and password on the TV, or scan the QR code with your phone on the same Wi-Fi. Use Test before Save. You can connect up to 5 providers.",
    "m.fs.fig1Alt": "IPTV Providers",
    "m.fs.fig1Cap": "IPTV Providers: provider list and add/edit (URL, username, password). Use Test before Save.",
    "m.fs.foldersH": "Select movie and series folders",
    "m.fs.foldersP": "After saving the provider: <strong>Select Movies and Series</strong> → mark the categories you want → Save &amp; Start Scan.",
    "m.fs.fig2Alt": "Categories",
    "m.fs.fig3Alt": "Scan",
    "m.fs.fig3Cap": "Scan fetches titles and matches posters/descriptions. The first run can take a long time.",
    "m.fs.liveH": "Seleccionar carpetas de TV (TV en vivo)",
    "m.fs.liveP": "On the same provider: <strong>Select TV Channels</strong> → mark the channel groups you want → <strong>Save TV Folders</strong>. Live TV and the program guide only show folders you selected.",
    "m.fs.liveP2": "If you open Live TV before selecting folders, the app shows a short setup guide that takes you back to Providers.",
