    "m.fs.xmltvP": "From IPTV Providers, choose <strong>+ Manage XMLTV</strong> to add up to 3 extra household-wide XMLTV lists, see EPG source status, or refresh all guides now. Lists can also be added with a QR code from your phone.",
    "m.fs.restoreH": "Restore from another TV",
