    "m.st.title": "Settings — SmartStream",
    "m.st.h1": "5. Ajustes",
    "m.st.lead": "Abre Ajustes en el menú izquierdo. Hay cuatro pantallas principales. Los nombres coinciden con los botones de la app.",
    "m.st.menuAlt": "Settings",
    "m.st.menuCap": "Settings hub: Accounts & Connections, Playback & Live TV, UI & Languages, Profile & System.",
    "m.st.thMenu": "Menu",
    "m.st.thWhat": "What it contains",
    "m.st.hub1": "Cuentas y conexiones",
    "m.st.hub1d": "IPTV providers, Gemini AI, Google Drive",
    "m.st.hub2": "Reproducción y TV en vivo",
    "m.st.hub2d": "Player, network, Live TV & EPG, audio",
    "m.st.hub3": "Interfaz e idiomas",
    "m.st.hub3d": "Subtitles, on-screen controls, app and metadata language",
    "m.st.hub4": "Perfil y sistema",
    "m.st.hub4d": "Parental PIN, ratings, diagnostics",
    "m.st.accountH": "Cuentas y conexiones",
    "m.st.accountAlt": "Accounts & Connections",
    "m.st.account1": "<strong>IPTV Providers</strong> — add up to 5 Xtream accounts (QR from phone or type on TV). Per provider: Test, Save, Select Movies and Series, Select TV Channels, max connections, and enable/disable playback for this profile.",
    "m.st.accountXmltv": "<strong>+ Manage XMLTV</strong> (on the provider screen) — EPG source status, refresh all guides now, and up to 3 custom XMLTV lists shared by the whole household.",
    "m.st.account2": "<strong>Gemini AI</strong> — API key for suggestions and natural-language search (primary profile). Can be skipped.",
    "m.st.account3": "<strong>Google Drive</strong> — Cloud Sync backup between TVs (primary profile).",
    "m.st.account4": "<strong>Manage Subscription</strong> — plans, billing, restore purchase.",
    "m.st.geminiAlt": "Gemini AI",
    "m.st.xmltvAlt": "Custom EPG lists",
    "m.st.xmltvCap": "Manage XMLTV — provider EPG status and custom XMLTV lists.",
    "m.st.subAlt": "Subscription",
    "m.st.playerH": "Reproducción y TV en vivo",
    "m.st.playerAlt": "Player & Network",
    "m.st.pnH": "Player & Network",
    "m.st.pn1": "<strong>Network Buffer Size</strong> — Small through Extra Large. Larger is more stable on slow networks; smaller starts faster.",
    "m.st.pn2": "<strong>Auto-switch poor encodes</strong> — hides 4K H.264 film streams in Details (they often judder). Dolby Vision and HEVC/H.265 are not affected. Also auto-switches 30 fps telecine encodes.",
    "m.st.pn3": "<strong>Intelligent Switching</strong> — automatically try another stream when playback fails.",
    "m.st.pn4": "<strong>Preferred stream quality</strong> — puts your chosen quality first in the long-press Play list (for example 4K UHD).",
    "m.st.liveH": "Live TV & EPG",
    "m.st.liveAlt": "Live TV & EPG",
    "m.st.live1": "<strong>Autoplay last channel</strong> — when you start the app, open Live TV on the last watched channel.",
    "m.st.live2": "<strong>EPG &amp; Program Guide</strong> — EPG days forward/back, program reminder lead time, <strong>EPG Channel Matcher</strong> (auto-match channels to the best XMLTV source), and <strong>External EPG &amp; Refresh</strong> (add up to 3 custom XMLTV lists and force guide refresh).",
    "m.st.liveIcon": "<strong>Channel Icon Matcher</strong> — auto-match, search, or customize channel logos for your folders.",
    "m.st.liveFavH": "Favorites",
    "m.st.live3": "Opens extra Live TV options:",
    "m.st.live3a": "<strong>EPG sidebar</strong> — All TV folders, or Favorite Channels (hides normal provider folders and opens directly into favorites).",
    "m.st.live3b": "<strong>Auto clean channel names in favorites</strong> — strip prefixes/suffixes from favorite names.",
    "m.st.live3c": "<strong>Find backup streams for favorites</strong> — find and attach backup streams on other providers for favorite channels.",
    "m.st.live3d": "<strong>Scan favorites</strong> — Missing or All: detect video/audio quality for favorites that have several streams.",
    "m.st.audioH": "Audio",
    "m.st.audio1": "<strong>Preferred language</strong> — first audio track when available.",
    "m.st.audio2": "<strong>Fallback language</strong> — used if the preferred track is missing.",
    "m.st.audio3": "<strong>HDMI Passthrough (Bitstream)</strong> — send Dolby/DTS unchanged to your sound system.",
    "m.st.langH": "Interfaz e idiomas",
    "m.st.langAlt": "UI & Languages",
    "m.st.subH": "Subtitles",
    "m.st.sub1": "<strong>Configure OpenSubtitles</strong> — optional account for online subtitles.",
    "m.st.sub2": "<strong>Preferred subtitle language</strong> — default language, fallback language, and Prioritize SDH subtitles (for hearing-impaired viewers).",
    "m.st.sub3": "<strong>Subtitle Appearance</strong> — font, size, colour, and position on screen.",
    "m.st.subAppAlt": "Subtitle appearance",
    "m.st.osAlt": "OpenSubtitles",
    "m.st.osAutoH": "OpenSubtitles: traducción y sincronización automáticas",
    "m.st.osAutoP": "¿No hay subtítulos en tu idioma? SmartStream puede encontrar un archivo en otro idioma y traducirlo por ti. Los subtítulos que van adelantados o atrasados se ajustan solos a la película.",
    "m.st.osTrH": "Activar la traducción automática",
    "m.st.osTr1": "<strong>Ajustes → Interfaz e idiomas → Subtítulos → Configure OpenSubtitles</strong> e inicia sesión con tu cuenta de OpenSubtitles (función Pro).",
    "m.st.osTr2": "<strong>Idioma de subtítulos preferido</strong>: elige el idioma que quieres leer. La traducción automática no se ejecuta si está en Ninguno o en inglés.",
    "m.st.osTr3": "Añade tu propia clave de Gemini en <strong>Ajustes → IA</strong> (una clave gratuita de Google AI Studio). La traducción usa tu clave.",
    "m.st.osTr4": "De vuelta en la página de OpenSubtitles, pon <strong>Translate OpenSubtitles</strong> en <strong>Enabled</strong>. Viene desactivado por defecto y se ajusta por perfil.",
    "m.st.osUseH": "Mientras ves",
    "m.st.osUse1": "Inicia una película o un episodio desde su página de detalles. Si ni la emisión ni OpenSubtitles tienen tu idioma, SmartStream elige un archivo en inglés (o en cualquier otro idioma si no hay inglés) y lo traduce.",
    "m.st.osUse2": "Aparece un círculo de progreso unos segundos. La película empieza en cuanto se traduce la primera parte y el resto se traduce mientras ves.",
    "m.st.osUse3": "El archivo traducido se guarda, así que la próxima vez empieza al instante. También funciona al hacer cast y desde Continuar viendo.",
    "m.st.osUse4": "Para elegir un archivo tú mismo, pulsa OK en el reproductor, luego <strong>Subs → OpenSubs</strong> y busca en cualquier idioma. Con el ajuste activado, los archivos en otros idiomas se traducen solos; si está desactivado, marca <strong>Traducir otros idiomas a …</strong>.",
    "m.st.osUse5": "La línea de información del menú OK muestra el archivo activo, por ejemplo <em>Danish (Opensubs, traducido)</em>.",
    "m.st.osSyncH": "Sincronización automática",
    "m.st.osSync1": "Cuando hay un archivo de OpenSubtitles activo, SmartStream comprueba su sincronía en segundo plano. Si la película tiene su propia pista de subtítulos, compara cuándo aparece el texto; si no, escucha cuándo se habla.",
    "m.st.osSync2": "Los subtítulos se ven con normalidad. Si van desfasados, el texto salta a su sitio, normalmente en menos de un minuto, y se afina en los minutos siguientes. Una película con una intro larga de música puede tardar un poco más.",
    "m.st.osSync3": "La corrección se guarda por archivo de subtítulos y llega a tus otros dispositivos con Cloud Sync, así que solo esperas la primera vez.",
    "m.st.osSync4": "Siempre puedes ajustar a mano con los botones <strong>Sub delay − / +</strong> del menú OK. Si la app no encuentra la sincronía, un aviso corto te lo recuerda.",
    "m.st.osNote": "La traducción necesita una clave de Gemini. Una clave gratuita tiene un límite diario; si se alcanza, ves el texto original y el resto se traduce la próxima vez.",
    "m.st.osdH": "Interface & OSD",
    "m.st.osd1": "<strong>Playback bar auto-hide delay</strong> — how long the control bar stays visible (or Off).",
    "m.st.osd2": "<strong>Show Grid Overlay</strong> — on-screen grid while browsing.",
    "m.st.osd3": "<strong>AI voice search</strong> — show the microphone in search for natural-language queries (needs Gemini).",
    "m.st.metaH": "Languages & Metadata",
