    "m.ix.figAlt": "HOME dashboard",
    "m.ix.figCap": "ACCUEIL — Reprendre la lecture, suggestions et Ma liste.",
    "m.ix.whatH": "Qu'est-ce que SmartStream ?",
    "m.ix.whatP": "Une app Android TV et Fire TV qui transforme votre compte IPTV en expérience salon : films et séries avec affiches, TV en direct avec guide, Reprendre la lecture, profils du foyer et recherche IA optionnelle. Les chaînes favorites peuvent porter des flux de secours d'autres fournisseurs, et Intelligent Switching bascule automatiquement si un flux échoue — aucune autre app IPTV ne le fait. Vous devez avoir votre propre fournisseur IPTV — SmartStream ne vend pas de contenu.",
    "m.ix.remoteH": "Télécommande",
