    "m.ix.remote4": "<strong>Maintenir OK</strong> sur une carte — note (👍/👎)",
    "m.ix.remote4b": "<strong>Hold OK</strong> on a Live TV channel or folder — favorites, backup streams, Change EPG, Change icon",
    "m.ix.remote5": "<strong>TV en direct plein écran :</strong> Haut/Bas change de chaîne, Gauche ouvre le guide, Droite revient à la chaîne précédente",
