    "m.ix.figCap": "HOME — Verder kijken, suggesties en Mijn lijst.",
    "m.ix.whatH": "Wat is SmartStream?",
    "m.ix.whatP": "Een Android TV- en Fire TV-app die van je eigen IPTV-account een woonkamerervaring maakt: films en series met posters, Live TV met een programmagids op het scherm, Verder kijken, huishoudprofielen en optionele AI-zoekfunctie. Favoriete zenders kunnen back-upstreams van andere providers bevatten, en Slim schakelen wisselt er automatisch tussen wanneer een stream wegvalt — iets wat geen enkele andere IPTV-app doet. Je hebt je eigen IPTV-provider nodig — SmartStream verkoopt geen content.",
    "m.ix.remoteH": "Afstandsbediening",
    "m.ix.remote1": "<strong>D-pad</strong> — verplaats de focus",
    "m.ix.remote2": "<strong>OK</strong> — selecteer",
    "m.ix.remote3": "<strong>Terug</strong> — één stap teruggaan (sluit de app niet af vanaf Home)",
    "m.ix.remote4": "<strong>OK ingedrukt houden</strong> op een film-/seriekaart — beoordeling (👍/👎)",
    "m.ix.remote4b": "<strong>OK ingedrukt houden</strong> op een Live TV-zender of map — favorieten, back-upstreams, EPG wijzigen, Pictogram wijzigen",
    "m.ix.remote5": "<strong>Live TV op volledig scherm:</strong> Omhoog/Omlaag zapt tussen zenders, Links opent de gids-overlay, Rechts springt terug naar de vorige zender",
    "m.ix.pagerHome": "← Productoverzicht",
    "m.ix.pagerNext": "Volgende: Aan de slag →",
