    "m.fs.iptvH": "IPTV-bron toevoegen",
    "m.fs.iptvP": "<strong>Instellingen → Accounts en verbindingen → IPTV-providers</strong>",
    "m.fs.iptvP2": "Je kunt de server-URL, gebruikersnaam en het wachtwoord op de tv typen, of de QR-code scannen met je telefoon op hetzelfde wifi-netwerk. Gebruik Testen vóór Opslaan. Je kunt tot 5 providers koppelen.",
    "m.fs.fig1Alt": "IPTV-providers",
    "m.fs.fig1Cap": "IPTV-providers: providerlijst en toevoegen/bewerken (URL, gebruikersnaam, wachtwoord). Gebruik Testen vóór Opslaan.",
    "m.fs.foldersH": "Film- en seriemappen selecteren",
    "m.fs.foldersP": "Na het opslaan van de provider: <strong>Selecteer films en series</strong> → vink de gewenste categorieën aan → Opslaan en scan starten.",
    "m.fs.fig2Alt": "Categorieën",
    "m.fs.fig3Alt": "Scannen",
    "m.fs.fig3Cap": "De scan haalt titels op en koppelt posters/beschrijvingen. De eerste keer kan dit lang duren.",
    "m.fs.liveH": "Tv-mappen selecteren (Live TV)",
    "m.fs.liveP": "Bij dezelfde provider: <strong>Selecteer tv-zenders</strong> → vink de gewenste zendergroepen aan → <strong>Tv-mappen opslaan</strong>. Live TV en de programmagids tonen alleen mappen die je hebt geselecteerd.",
    "m.fs.liveP2": "Als je Live TV opent voordat je mappen hebt geselecteerd, toont de app een korte installatiegids die je terugbrengt naar Providers.",
    "m.fs.fig4Alt": "Tv-mappen selecteren",
    "m.fs.fig4Cap": "Tv-mappen selecteren — kies de zendergroepen die dit profiel in Live TV moet zien.",
    "m.fs.xmltvH": "Optioneel: eigen tv-gids (XMLTV)",
    "m.fs.xmltvP": "Kies bij IPTV-providers voor <strong>+ XMLTV beheren</strong> om tot 3 extra XMLTV-lijsten voor het hele huishouden toe te voegen, de status van EPG-bronnen te bekijken of alle gidsen nu te vernieuwen. Lijsten kunnen ook met een QR-code vanaf je telefoon worden toegevoegd.",
    "m.fs.restoreH": "Herstellen vanaf een andere tv",
    "m.fs.restoreP": "Tijdens het instellen: kies <strong>Herstellen</strong> en voer je Cloud Sync-pincode en Google-account in.",
    "m.fs.restoreLink": "Cloud Sync voor gebruikers →",
