    "m.pr.kidsH": "Kinderprofiel",
    "m.pr.kidsP": "Schakel <strong>Kinderprofiel</strong> in bij het aanmaken. Vergrendelde content en pincodevragen worden verborgen.",
    "m.pr.kidsAlt": "Kinderprofiel",
    "m.pr.pinH": "Pincode voor ouderlijk toezicht",
    "m.pr.pinP": "Instellingen → Profiel en systeem → Pincode voor ouderlijk toezicht. Je kunt gekozen content en Live TV-mappen vergrendelen zodat de pincode vereist is.",
    "m.pr.liveH": "Live TV per profiel",
    "m.pr.liveP": "Bij extra profielen kun je <strong>Primaire tv-instelling</strong> aanzetten. Dan gebruikt dat profiel dezelfde tv-mappen, favorieten, zendervolgorde en gidskoppelingen als het eerste profiel. Zet het uit om zelfstandig mappen te kiezen.",
    "m.pr.primaryH": "Hoofdprofiel",
    "m.pr.primaryP": "Het eerste profiel beheert de instellingen voor Cloud Sync, Google Gemini en TMDB. Het kan niet worden verwijderd.",
