    "m.mc.c_count": "Geheel getal; een lijst wordt geteld",
    "m.mc.c_text": "Platte tekst of YouTube-video-ID",
    "m.mc.c_number": "Getal",
    "m.mc.pathsH": "Veldpaden schrijven",
    "m.mc.paths1": "<code>a.b</code> — een veld in een object (bijvoorbeeld <code>coverImage.extraLarge</code>)",
    "m.mc.paths2": "<code>a|b</code> — gebruik <code>b</code> wanneer <code>a</code> leeg is (bijvoorbeeld <code>title.english|title.romaji</code>)",
    "m.mc.paths3": "<code>list[*].name</code> — elke naam in een lijst (bijvoorbeeld <code>studios.nodes[*].name</code>)",
    "m.mc.paths4": "<code>$</code> — het antwoord zelf is de resultatenlijst",
    "m.mc.paths5": "Plaatsaanduidingen in paden, parameters en POST-body's: <code>{query}</code>, <code>{year}</code>, <code>{id}</code>, <code>{season}</code>, <code>{api_key}</code>.",
    "m.mc.examplesH": "Volledige JSON-voorbeelden",
    "m.mc.exAnilist": "<strong>AniList</strong> (animefilms en -series, gratis, geen sleutel). Dit is de volledige ingebouwde verzamelaar die <code>POST</code> en GraphQL gebruikt:",
    "m.mc.exTvmaze": "<strong>TVMaze</strong> (series, gratis, geen sleutel — eenvoudig <code>GET</code>-verzoek waarbij de resultaten het antwoord zelf zijn, <code>$</code>):",
    "m.mc.exOmdb": "<strong>OMDb</strong> (films en series, gratis sleutel van omdbapi.com). De sleutel gaat in de URL-parameter <code>apikey</code>; details worden opgehaald via IMDb-ID:",
    "m.mc.rulesH": "Regels voor verzamelaars",
