    "m.du.liveIntro": "Åpne <strong>Live-TV</strong> i venstremenyen. Du får en programguide (EPG) med direktesendt forhåndsvisning. Trykk OK på gjeldende program for å se i fullskjerm — bildet fortsetter uten å koble til på nytt.",
