    "m.du.liveGuideH": "Guide og mapper",
    "m.du.live1": "Venstre sidefelt viser dine valgte TV-mapper (per leverandør).",
    "m.du.live2": "Favorittkanaler ligger øverst så snart du stjernemerker kanaler eller flytter mapper under favoritter.",
    "m.du.live3": "Søk i guiden fra sidemenyen for å finne et program eller en kanal.",
    "m.du.live4": "Hvis leverandøren din støtter arkiv-TV (catch-up), kan du starte et tidligere program rett fra guiden.",
