    "m.du.liveFav1": "<strong>Legg til en kanal:</strong> hold inne <strong>OK</strong> på en kanal i guiden og velg <strong>Legg til i favoritter</strong>.",
    "m.du.liveFav2": "<strong>Legg til eller flytt en hel mappe:</strong> hold inne <strong>OK</strong> på en mappe i sidefeltet for å velge <strong>Legg til alle kanaler i favoritter</strong> eller <strong>Flytt mappe under favoritter</strong> slik at den blir en favorittmappe.",
    "m.du.liveFavGroup": "<strong>Kanalgrupper inne i Favoritter:</strong> hold inne <strong>OK</strong> på en kanal i Favorittkanaler og velg <strong>Legg til kanalgruppe over</strong> for å opprette seksjoner, eller <strong>Flytt kanal/grupper</strong> for å endre rekkefølgen.",
    "m.du.liveFavHide": "<strong>Skjul vanlige TV-mapper:</strong> gå til <strong>Innstillinger → Avspilling &amp; Live-TV → Live-TV &amp; EPG → Favoritter → EPG-sidefelt</strong> og bytt fra <em>Alle TV-mapper</em> til <em>Favorittkanaler</em>. Vanlige leverandørmapper skjules slik at bare favorittene og favorittmappene dine vises, og Live-TV åpner rett i favorittene.",
