    "m.du.liveFavH": "Reservestrømmer for favorittkanaler",
    "m.du.liveMultiP": "En favoritt er ikke begrenset til én leverandør. Du kan knytte ekstra reservestrømmer fra andre leverandører til den samme favorittkanalen. Hvis én kilde er opptatt eller faller ut, er en annen strøm allerede koblet til.",
    "m.du.liveMultiLong": "<strong>Fra hurtigmenyen (hold inne OK):</strong> hold inne <strong>OK</strong> på en hvilken som helst kanal i en vanlig mappe og velg <strong>Bruk som reserve for en favoritt</strong> for å koble den direkte — eller hold inne <strong>OK</strong> på en kanal og velg <strong>Finn reservestrømmer for favoritter</strong>. På en favoritt som allerede har reserver, velger du <strong>Se alle strømmer</strong> for å se eller fjerne dem.",
    "m.du.liveMulti1": "<strong>Fra Innstillinger:</strong> åpne <strong>Innstillinger → Avspilling &amp; Live-TV → Live-TV &amp; EPG → Favoritter → Finn reservestrømmer for favoritter</strong>. Du kan også kjøre <strong>Skann favoritter</strong> (Manglende eller Alle) der for å teste video- og lydkvalitet på koblede strømmer.",
    "m.du.liveMulti2": "Spillermenyen (OK i fullskjerm) lar deg bytte strøm manuelt hvis flere er koblet til.",
    "m.du.liveLongAlt": "Hurtigmeny for Live-TV",
    "m.du.liveLongCap": "Hurtigmeny (hold inne OK på en kanal) — favoritter, reservestrømmer, Bytt EPG og Endre ikon.",
    "m.du.liveLinkAlt": "Finn reservestrømmer for favoritter",
    "m.du.liveLinkCap": "Finn reservestrømmer for favoritter — match og knytt reservestrømmer fra andre leverandører.",
    "m.du.liveMultiNote": "Koblede reserver er det <a href=\"daily-switching.html\">Intelligent strømbytting</a> bruker når en strøm svikter.",
    "m.du.epgMgrH": "EPG-behandler (EPG &amp; programguide)",
    "m.du.epgMgrP": "Åpne <strong>Innstillinger → Avspilling &amp; Live-TV → Live-TV &amp; EPG → EPG &amp; programguide</strong> for å administrere TV-guidekilder og kanalmatching.",
    "m.du.epgMgr1": "<strong>Legg til din egen EPG-liste:</strong> velg <strong>Ekstern EPG &amp; oppdatering</strong> (også tilgjengelig via <strong>+ Administrer XMLTV</strong> på IPTV-leverandører) for å se leverandørens EPG-status, tvinge en oppdatering av alle guider nå, eller legge til opptil <strong>3 egendefinerte XMLTV-URL-er</strong> (skrevet inn eller skannet via QR fra mobilen). Egendefinerte lister deles i hele husstanden.",
    "m.du.epgMgr2": "<strong>Automatisk matching av kanaler til beste tilgjengelige EPG:</strong> åpne <strong>EPG-kanalmatching</strong> og trykk <strong>Automatisk matching</strong>. SmartStream skanner alle leverandør-EPG-ene og dine egendefinerte XMLTV-lister og matcher hver kanal til den beste tilgjengelige guiden. Du kan filtrere etter <em>Alle</em>, <em>Foreslåtte</em> eller <em>Ikke matchet</em>, bytte mappe (f.eks. Favorittkanaler) eller søke manuelt.",
    "m.du.epgMgr3": "<strong>Enkeltkanal i guiden:</strong> du kan også holde inne <strong>OK</strong> på en hvilken som helst kanal i Live-TV og velge <strong>Bytt EPG</strong> for å velge eller tilbakestille guiden bare for den kanalen.",
    "m.du.epgMgrAlt": "Innstillinger for EPG & programguide",
    "m.du.epgMgrCap": "EPG &amp; programguide — dager fremover/bakover, påminnelser, EPG-kanalmatching og Ekstern EPG &amp; oppdatering.",
    "m.du.epgMatchAlt": "EPG-kanalmatching",
    "m.du.epgMatchCap": "EPG-kanalmatching — Automatisk matching, filtre og anbefalte EPG-treff på tvers av kilder.",
    "m.du.iconH": "TV-kanalikoner",
    "m.du.icon1": "<strong>Fra hurtigmenyen (hold inne OK):</strong> hold inne <strong>OK</strong> på en kanal i Live-TV-guiden og velg <strong>Endre ikon</strong>. Du kan velge logoer fra strømmen, EPG-en eller den innebygde logokatalogen (med pikseloppløsning vist), eller velge <strong>Tilbakestill til original</strong>.",
    "m.du.icon2": "<strong>Automatisk matching fra Innstillinger:</strong> åpne <strong>Innstillinger → Avspilling &amp; Live-TV → Live-TV &amp; EPG → Kanalikonmatching</strong> og trykk <strong>Automatisk</strong> for å automatisk finne og bruke de beste kanallogoene for alle kanaler i den valgte mappen. Du kan også filtrere på <em>Egendefinerte</em> vs <em>Original</em>, søke manuelt blant alle logoer eller tilbakestille kanaler til sin opprinnelige strømlogo.",
    "m.du.iconDlgAlt": "Dialog for å endre kanalikon",
    "m.du.iconDlgCap": "Endre ikon fra hurtigmenyen — velg fra strøm, EPG eller egendefinerte logoer.",
    "m.du.iconMgrAlt": "Kanalikonmatching",
    "m.du.iconMgrCap": "Kanalikonmatching i Innstillinger — match automatisk de beste logoene for en hel mappe.",
    "m.du.liveFsH": "Fullskjerm",
    "m.du.liveFsAlt": "Live-TV i fullskjerm",
    "m.du.liveFs1": "<strong>Opp / Ned</strong> — bytt til neste eller forrige kanal",
    "m.du.liveFs2": "<strong>Venstre</strong> — åpne programguiden som overlegg på skjermen",
    "m.du.liveFs3": "<strong>Høyre</strong> — hopp tilbake til forrige kanal",
    "m.du.liveFs4": "<strong>OK</strong> — spillermeny (info, spor, strømbytte hvis flere strømmer er koblet til)",
    "m.du.liveFs5": "<strong>Tilbake</strong> — gå tilbake til guiden (lukker ikke appen)",
    "m.du.liveFsNote": "Favorittkanaler kan ha flere strømmer fra ulike leverandører. Intelligent bytting går automatisk over til en reserve når den gjeldende strømmen er opptatt eller svikter — unikt for SmartStream.",
    "m.du.ratingsH": "Vurdering",
    "m.du.ratingsP": "Vurderinger lærer appen hva du liker. Foreslåtte filmer og Foreslåtte serier på Hjem bruker tommel opp/ned sammen med en Google Gemini API-nøkkel.",
    "m.du.ratings1": "Hold inne <strong>OK</strong> på et kort for 👍 / 👎",
    "m.du.ratings2": "Legg til i Min liste fra detaljskjermen",
    "m.du.ratings3": "Vurderinger lagres per profil og synkroniseres med Cloud Sync",
    "m.du.ratingAlt": "Vurdering",
    "m.du.searchH": "AI-søk",
    "m.du.searchP": "Søkeikonet i Filmer/Serier, eller tale på Google TV hvis AI-talesøk er aktivert under Innstillinger → Grensesnitt & språk → Grensesnitt & OSD.",
    "m.du.searchP2": "Søket leter i ditt eget bibliotek — ikke på hele internett. Du kan skrive, eller snakke på Google TV.",
    "m.du.search1": "Åpne søkeikonet på Filmer- eller Serier-skjermen.",
    "m.du.search2": "Spør med naturlig språk, for eksempel «et krimdrama fra 90-tallet» eller «en zombiefilm med mørk humor».",
    "m.du.search3": "Talesøk på Google TV: aktiver det under Innstillinger → Grensesnitt & språk → Grensesnitt & OSD.",
    "m.du.search4": "AI-søk krever en Google Gemini API-nøkkel under Innstillinger → Kontoer & tilkoblinger → Gemini AI.",
    "m.du.searchAlt": "AI-søk",
    "m.du.switchTitle": "Daglig bruk — Intelligent strømbytting — SmartStream",
    "m.du.switchPageH": "3. Daglig bruk — Intelligent strømbytting",
    "m.du.switchLead": "Intelligent bytting mellom leverandører: Når avspillingen svikter eller en annen enhet tar plassen, bytter SmartStream automatisk. Ingen annen IPTV-app gjør dette.",
    "m.du.switchWhatH": "Hva det gjør",
    "m.du.switchP": "De fleste IPTV-apper stopper når en strøm svikter eller når en annen TV i huset bruker den samme innloggingsplassen. SmartStream ser etter en annen strøm du allerede har koblet til — fra en annen leverandør om nødvendig — og fortsetter avspillingen.",
    "m.du.switchLi1": "<strong>Live-TV:</strong> reservestrømmer knyttet til en favorittkanal.",
    "m.du.switchLi2": "<strong>Filmer og serier:</strong> en annen kopi av den samme tittelen fra en annen leverandør.",
    "m.du.switchLi3": "<strong>Plass opptatt:</strong> hvis en annen enhet bruker en leverandør, kan SmartStream be den TV-en om å frigjøre den, og deretter bytte.",
    "m.du.switchHowH": "Slik setter du det opp",
    "m.du.switchHow1": "Koble til mer enn én IPTV-leverandør (opptil 5).",
    "m.du.switchHow2": "Live-TV: Knytt reservestrømmer (se <a href=\"daily-live-tv.html\">Live-TV</a>).",
    "m.du.switchHow3": "Filmer/serier: Importer de samme titlene fra mer enn én leverandør.",
    "m.du.switchHow4": "Slå på Intelligent bytting under Innstillinger → Avspilling & Live-TV → Spiller & nettverk.",
    "m.du.switchSetP": "Du kan fortsatt bytte strøm manuelt fra spillermenyen (OK under avspilling).",
