    "m.pr.pinP": "Innstillinger → Profil & system → PIN for foreldrekontroll. Du kan låse utvalgt innhold og Live-TV-mapper slik at de krever PIN.",
    "m.pr.liveH": "Live-TV per profil",
    "m.pr.liveP": "På ekstra profiler kan du slå på <strong>Hovedprofilens TV-oppsett</strong>. Da bruker profilen de samme TV-mappene, favorittene, kanalrekkefølgen og guidekoblingene som den første profilen. Slå det av for å velge mapper uavhengig.",
