    "m.fs.iptvH": "Lägg till IPTV-källa",
    "m.fs.iptvP": "<strong>Inställningar → Konton &amp; anslutningar → IPTV-leverantörer</strong>",
    "m.fs.iptvP2": "Du kan skriva in server-URL, användarnamn och lösenord på TV:n, eller skanna QR-koden med mobilen på samma Wi-Fi. Använd Testa före Spara. Du kan ansluta upp till 5 leverantörer.",
    "m.fs.fig1Alt": "IPTV-leverantörer",
    "m.fs.fig1Cap": "IPTV-leverantörer: leverantörslista och lägg till/redigera (URL, användarnamn, lösenord). Använd Testa före Spara.",
    "m.fs.foldersH": "Välj film- och seriemappar",
    "m.fs.foldersP": "Efter att leverantören har sparats: <strong>Välj filmer och serier</strong> → markera de kategorier du vill ha → Spara &amp; starta skanning.",
    "m.fs.fig2Alt": "Kategorier",
    "m.fs.fig3Alt": "Skanna",
    "m.fs.fig3Cap": "Skanningen hämtar titlar och matchar affischer och beskrivningar. Första körningen kan ta lång tid.",
    "m.fs.liveH": "Välj TV-mappar (Live-TV)",
    "m.fs.liveP": "På samma leverantör: <strong>Välj TV-kanaler</strong> → markera de kanalgrupper du vill ha → <strong>Spara TV-mappar</strong>. Live-TV och programguiden visar bara mappar du har valt.",
    "m.fs.liveP2": "Om du öppnar Live-TV innan du har valt mappar visar appen en kort installationsguide som tar dig tillbaka till Leverantörer.",
    "m.fs.fig4Alt": "Välj TV-mappar",
    "m.fs.fig4Cap": "Välj TV-mappar — välj vilka kanalgrupper den här profilen ska se i Live-TV.",
    "m.fs.xmltvH": "Valfritt: egen TV-guide (XMLTV)",
    "m.fs.xmltvP": "Från IPTV-leverantörer väljer du <strong>+ Hantera XMLTV</strong> för att lägga till upp till 3 extra XMLTV-listor för hela hushållet, se status för EPG-källor eller uppdatera alla guider nu. Listor kan också läggas till med en QR-kod från mobilen.",
    "m.fs.restoreH": "Återställ från en annan TV",
    "m.fs.restoreP": "Under installationen: välj <strong>Återställ</strong> och ange din Cloud Sync-PIN och ditt Google-konto.",
    "m.fs.restoreLink": "Cloud Sync för användare →",
