    "m.pr.kidsH": "Barnprofil",
    "m.pr.kidsP": "Aktivera <strong>Barnprofil</strong> när du skapar den. Låst innehåll och PIN-frågor döljs.",
    "m.pr.kidsAlt": "Barnprofil",
    "m.pr.pinH": "PIN för föräldrakontroll",
    "m.pr.pinP": "Inställningar → Profil & system → PIN för föräldrakontroll. Du kan låsa valt innehåll och Live-TV-mappar så att de kräver PIN.",
    "m.pr.liveH": "Live-TV per profil",
    "m.pr.liveP": "På extra profiler kan du slå på <strong>Huvudprofilens TV-inställningar</strong>. Då använder den profilen samma TV-mappar, favoriter, kanalordning och guidekopplingar som den första profilen. Stäng av det för att välja mappar självständigt.",
    "m.pr.primaryH": "Huvudprofil",
    "m.pr.primaryP": "Den första profilen styr inställningarna för Cloud Sync, Google Gemini och TMDB. Den kan inte tas bort.",
