    "m.mc.c_number": "Nummer",
    "m.mc.pathsH": "Skriva fältsökvägar",
    "m.mc.paths1": "<code>a.b</code> — ett fält inuti ett objekt (till exempel <code>coverImage.extraLarge</code>)",
    "m.mc.paths2": "<code>a|b</code> — använd <code>b</code> när <code>a</code> är tomt (till exempel <code>title.english|title.romaji</code>)",
    "m.mc.paths3": "<code>list[*].name</code> — varje namn i en lista (till exempel <code>studios.nodes[*].name</code>)",
    "m.mc.paths4": "<code>$</code> — själva svaret är resultatlistan",
    "m.mc.paths5": "Platshållare i sökvägar, parametrar och POST-texter: <code>{query}</code>, <code>{year}</code>, <code>{id}</code>, <code>{season}</code>, <code>{api_key}</code>.",
    "m.mc.examplesH": "Fullständiga JSON-exempel",
    "m.mc.exAnilist": "<strong>AniList</strong> (animefilmer och -serier, gratis, ingen nyckel). Det här är den kompletta inbyggda insamlaren som använder <code>POST</code> och GraphQL:",
    "m.mc.exTvmaze": "<strong>TVMaze</strong> (serier, gratis, ingen nyckel — enkel <code>GET</code>-begäran där resultaten är själva svaret, <code>$</code>):",
    "m.mc.exOmdb": "<strong>OMDb</strong> (filmer och serier, gratis nyckel från omdbapi.com). Nyckeln placeras i URL-parametern <code>apikey</code>; detaljer hämtas med IMDb-ID:",
    "m.mc.rulesH": "Regler för insamlare",
    "m.mc.rules1": "Använd bara källor du har tillåtelse att använda och följ varje källas egna villkor och begäransgränser.",
    "m.mc.rules2": "Insamlare för olagligt innehåll eller begränsat innehåll som bryter mot butikens policyer är inte tillåtna. Skapa, dela eller använd dem inte med SmartStream.",
    "m.mc.rules3": "SmartStream levererar inga insamlare för sådana källor och har ingen insamlarbutik.",
