    "m.ix.whatH": "Mikä on SmartStream?",
    "m.ix.whatP": "Android TV- ja Fire TV -sovellus, joka muuttaa oman IPTV-tilisi olohuonekokemukseksi: elokuvat ja sarjat julisteilla, Live TV ruutuoppaalla, Jatka katselua, kotitalouden profiilit ja valinnainen tekoälyhaku. Suosikkikanavilla voi olla varalähetyksiä muilta palveluntarjoajilta, ja Älykäs vaihto siirtyy niiden välillä automaattisesti lähetyksen katketessa — ominaisuus, jota mikään muu IPTV-sovellus ei tarjoa. Tarvitset oman IPTV-palveluntarjoajan — SmartStream ei myy sisältöä.",
