    "m.du.homeH": "ETUSIVU",
    "m.du.homeP": "Etusivu on vasemman valikon ensimmäinen kohta. Se näyttää, mitä olit katsomassa, mitä sovellus ehdottaa ja tallentamasi nimikkeet.",
