    "m.tr.p2c": "Live TV: jos toinen laite käyttää samaa IPTV-kirjautumista, suosikit linkitetyillä varalähetyksillä voivat vaihtaa automaattisesti",
    "m.tr.p3h": "Cloud Sync ei päivity",
