    "m.ix.figCap": "STRONA GŁÓWNA — Oglądaj dalej, propozycje i Moja lista.",
    "m.ix.whatH": "Czym jest SmartStream?",
    "m.ix.whatP": "Aplikacją na Android TV i Fire TV, która zamienia Twoje własne konto IPTV w prawdziwe kino domowe: filmy i seriale z plakatami, Live TV z przewodnikiem ekranowym, Oglądaj dalej, profile domowników oraz opcjonalne wyszukiwanie AI. Ulubione kanały mogą mieć przypisane zapasowe strumienie od innych dostawców, a inteligentne przełączanie automatycznie przechodzi między nimi, gdy strumień zawiedzie — nie robi tego żadna inna aplikacja IPTV. Potrzebujesz własnego dostawcy IPTV — SmartStream nie sprzedaje treści.",
