    "m.du.homeH": "STRONA GŁÓWNA",
    "m.du.homeP": "Strona główna to pierwsza pozycja w lewym menu. Pokazuje, co było oglądane, co proponuje aplikacja oraz zapisane przez Ciebie tytuły.",
    "m.du.homeP2": "Użyj lewego menu, aby otworzyć Live TV, Filmy lub Seriale. Ustawienia znajdują się na dole tego samego menu.",
    "m.du.homeAlt": "STRONA GŁÓWNA",
    "m.du.home1": "<strong>Oglądaj dalej</strong> — wznów filmy lub seriale",
