    "m.tr.p2b": "Ustawienia → Odtwarzanie i Live TV → Odtwarzacz i sieć → Inteligentne przełączanie i Automatycznie przełączaj słabe kodowania",
    "m.tr.p2c": "Live TV: jeśli inne urządzenie używa tego samego loginu IPTV, ulubione z podpiętymi strumieniami zapasowymi mogą przełączyć się automatycznie",
