    "m.ix.figAlt": "Painel INÍCIO",
    "m.ix.figCap": "INÍCIO — Continuar a Ver, sugestões e A Minha Lista.",
    "m.ix.whatH": "O que é o SmartStream?",
    "m.ix.whatP": "Uma aplicação para Android TV e Fire TV que transforma a sua própria conta IPTV numa experiência de sala de estar: filmes e séries com pósteres, TV em Direto com guia no ecrã, Continuar a Ver, perfis familiares e pesquisa opcional com IA. Os canais favoritos podem ter streams de reserva de outros fornecedores e a Troca Inteligente alterna automaticamente entre eles quando um stream falha — algo que nenhuma outra aplicação IPTV faz. Precisa do seu próprio fornecedor IPTV — o SmartStream não vende conteúdos.",
