    "m.fs.iptvP2": "Pode escrever o URL do servidor, o nome de utilizador e a palavra-passe na TV, ou ler o código QR com o telemóvel na mesma rede Wi-Fi. Utilize Testar antes de Guardar. Pode ligar até 5 fornecedores.",
    "m.fs.fig1Alt": "Fornecedores IPTV",
