    "m.fs.foldersP": "Depois de guardar o fornecedor: <strong>Selecionar Filmes e Séries</strong> → marque as categorias pretendidas → Guardar e Iniciar Análise.",
    "m.fs.fig2Alt": "Categorias",
    "m.fs.fig3Alt": "Análise",
    "m.fs.fig3Cap": "A análise obtém os títulos e associa pósteres/descrições. A primeira execução pode demorar bastante tempo.",
    "m.fs.liveH": "Selecionar pastas de TV (TV em Direto)",
    "m.fs.liveP": "No mesmo fornecedor: <strong>Selecionar Canais de TV</strong> → marque os grupos de canais pretendidos → <strong>Guardar Pastas de TV</strong>. A TV em Direto e o guia de programação mostram apenas as pastas selecionadas.",
    "m.fs.liveP2": "Se abrir a TV em Direto antes de selecionar pastas, a aplicação mostra um guia rápido de configuração que o leva de volta a Fornecedores.",
    "m.fs.fig4Alt": "Selecionar pastas de TV",
