    "m.fs.xmltvH": "Opcional: guia de TV personalizado (XMLTV)",
    "m.fs.xmltvP": "Em Fornecedores IPTV, escolha <strong>+ Gerir XMLTV</strong> para adicionar até 3 listas XMLTV extra partilhadas por toda a casa, ver o estado da fonte EPG ou atualizar todos os guias agora. As listas também podem ser adicionadas com um código QR a partir do telemóvel.",
    "m.fs.restoreH": "Restaurar a partir de outra TV",
    "m.fs.restoreP": "Durante a configuração: escolha <strong>Restaurar</strong> e introduza o seu PIN do Cloud Sync e a sua conta Google.",
    "m.fs.restoreLink": "Cloud Sync para utilizadores →",
