    "m.pr.up5_4": "Seleção de pastas de filmes e séries por fonte IPTV (se configurado)",
    "m.pr.up5_5": "Pastas de TV em Direto, favoritos e guia — ou partilhar a configuração de TV do perfil principal",
    "m.pr.kidsH": "Perfil infantil",
    "m.pr.kidsP": "Ative <strong>Perfil infantil</strong> ao criá-lo. Os conteúdos bloqueados e pedidos de PIN ficam ocultos.",
    "m.pr.kidsAlt": "Perfil infantil",
    "m.pr.pinH": "PIN de Controlo Parental",
    "m.pr.pinP": "Definições → Perfil e Sistema → PIN de Controlo Parental. Pode bloquear conteúdos selecionados e pastas de TV em Direto para que exijam o PIN.",
    "m.pr.liveH": "TV em Direto por perfil",
    "m.pr.liveP": "Nos perfis extra pode ativar <strong>Configuração principal de TV</strong>. Assim, esse perfil usa as mesmas pastas de TV, favoritos, ordem de canais e associações do guia que o primeiro perfil. Desative para escolher pastas de forma independente.",
    "m.pr.primaryH": "Perfil principal",
    "m.pr.primaryP": "O primeiro perfil controla as definições do Cloud Sync, Gemini e TMDB. Não pode ser eliminado.",
    "m.pr.pagerPrev": "← Troca inteligente de stream",
