    "m.ix.whatP": "Um aplicativo para Android TV e Fire TV que transforma sua própria conta IPTV em uma experiência de sala de estar: filmes e séries com pôsteres, TV ao Vivo com guia na tela, Continuar Assistindo, perfis familiares e busca opcional com IA. Canais favoritos podem ter streams reserva de outros provedores e a Troca Inteligente alterna entre eles automaticamente quando um stream falha — algo que nenhum outro app de IPTV faz. Você precisa do seu próprio provedor IPTV — o SmartStream não vende conteúdo.",
