    "m.pr.up5_1": "Continuar Assistindo e Minha Lista",
    "m.pr.up5_2": "Avaliações (👍/👎)",
    "m.pr.up5_3": "Filtros de navegação para Filmes e Séries",
    "m.pr.up5_4": "Seleção de pastas de filmes e séries por fonte IPTV (se configurado)",
    "m.pr.up5_5": "Pastas da TV ao Vivo, favoritos e guia — ou compartilhar a configuração de TV do perfil principal",
    "m.pr.kidsH": "Perfil infantil",
    "m.pr.kidsP": "Ative <strong>Perfil infantil</strong> ao criá-lo. Conteúdos bloqueados e solicitações de PIN ficam ocultos.",
    "m.pr.kidsAlt": "Perfil infantil",
    "m.pr.pinH": "PIN de Controle Parental",
    "m.pr.pinP": "Configurações → Perfil e Sistema → PIN de Controle Parental. Você pode bloquear conteúdos selecionados e pastas da TV ao Vivo para exigir o PIN.",
    "m.pr.liveH": "TV ao Vivo por perfil",
    "m.pr.liveP": "Nos perfis extras você pode ativar <strong>Configuração principal de TV</strong>. Assim esse perfil usa as mesmas pastas de TV, favoritos, ordem dos canais e mapeamentos do guia que o primeiro perfil. Desative para escolher pastas de forma independente.",
    "m.pr.primaryH": "Perfil principal",
    "m.pr.primaryP": "O primeiro perfil controla as configurações do Cloud Sync, Gemini e TMDB. Ele não pode ser excluído.",
    "m.pr.pagerPrev": "← Troca inteligente de stream",
