    "m.ix.figAlt": "Ana sayfa panosu",
    "m.ix.figCap": "ANA SAYFA — İzlemeye devam et, öneriler ve Listem.",
    "m.ix.whatH": "SmartStream nedir?",
    "m.ix.whatP": "Kendi IPTV hesabınızı bir oturma odası deneyimine dönüştüren bir Android TV ve Fire TV uygulaması: afişli filmler ve diziler, ekran rehberli Canlı TV, İzlemeye devam et, hane profilleri ve isteğe bağlı yapay zeka araması. Favori kanallar diğer sağlayıcılardan yedek yayınlar taşıyabilir ve bir yayın başarısız olduğunda Akıllı Geçiş bunlar arasında otomatik geçiş yapar — başka hiçbir IPTV uygulamasının yapmadığı bir özellik. Kendi IPTV sağlayıcınıza ihtiyacınız vardır — SmartStream içerik satmaz.",
    "m.ix.remoteH": "Uzaktan kumanda",
    "m.ix.remote1": "<strong>D-pad</strong> — odağı hareket ettir",
    "m.ix.remote2": "<strong>OK</strong> — seç",
    "m.ix.remote3": "<strong>Geri</strong> — bir adım geri git (Ana sayfadan uygulamadan çıkmaz)",
    "m.ix.remote4": "Bir film/dizi kartında <strong>OK tuşunu basılı tut</strong> — puanlama (👍/👎)",
    "m.ix.remote4b": "Bir Canlı TV kanalında veya klasöründe <strong>OK tuşunu basılı tut</strong> — favoriler, yedek yayınlar, EPG değiştir, Simge değiştir",
    "m.ix.remote5": "<strong>Canlı TV tam ekran:</strong> Yukarı/Aşağı kanalları değiştirir, Sol rehber katmanını açar, Sağ önceki kanala atlar",
