    "m.fs.newP": "Uygulama genellikle sizi şu sırayla yönlendirir:",
    "m.fs.new1": "Uygulama dili",
    "m.fs.new2": "Yeni cihaz veya buluttan geri yükleme",
    "m.fs.new3": "Profil oluşturma (ad, avatar, isteğe bağlı çocuk profili)",
    "m.fs.new4": "Cloud Sync — atlanabilir",
    "m.fs.new5": "Gemini API — atlanabilir",
    "m.fs.new6": "Meta veri dili (TMDB)",
