    "m.fs.new9": "Film ve dizi klasörlerini seç → tara",
    "m.fs.iptvH": "IPTV kaynağı ekle",
    "m.fs.iptvP": "<strong>Ayarlar → Hesaplar ve bağlantılar → IPTV sağlayıcıları</strong>",
    "m.fs.iptvP2": "Sunucu URL'sini, kullanıcı adını ve şifreyi TV üzerinden yazabilir veya aynı Wi-Fi ağındaki telefonunuzla QR kodunu okutabilirsiniz. Kaydetmeden önce Test et'i kullanın. 5 adede kadar sağlayıcı bağlayabilirsiniz.",
    "m.fs.fig1Alt": "IPTV sağlayıcıları",
    "m.fs.fig1Cap": "IPTV sağlayıcıları: sağlayıcı listesi ve ekle/düzenle (URL, kullanıcı adı, şifre). Kaydetmeden önce Test et'i kullanın.",
    "m.fs.foldersH": "Film ve dizi klasörlerini seçin",
    "m.fs.foldersP": "Sağlayıcıyı kaydettikten sonra: <strong>Film ve dizileri seç</strong> → istediğiniz kategorileri işaretleyin → Kaydet ve Taramayı Başlat.",
    "m.fs.fig2Alt": "Kategoriler",
    "m.fs.fig3Alt": "Tarama",
    "m.fs.fig3Cap": "Tarama, başlıkları alır ve afişlerle açıklamaları eşleştirir. İlk çalıştırma uzun sürebilir.",
    "m.fs.liveH": "TV klasörlerini seçin (Canlı TV)",
    "m.fs.liveP": "Aynı sağlayıcıda: <strong>TV kanallarını seç</strong> → istediğiniz kanal gruplarını işaretleyin → <strong>TV klasörlerini kaydet</strong>. Canlı TV ve program rehberi yalnızca seçtiğiniz klasörleri gösterir.",
    "m.fs.liveP2": "Klasörleri seçmeden önce Canlı TV'yi açarsanız, uygulama sizi Sağlayıcılara geri götüren kısa bir kurulum rehberi gösterir.",
    "m.fs.fig4Alt": "TV klasörlerini seç",
    "m.fs.fig4Cap": "TV klasörlerini seç — bu profilin Canlı TV'de göreceği kanal gruplarını seçin.",
    "m.fs.xmltvH": "İsteğe bağlı: özel TV rehberi (XMLTV)",
    "m.fs.xmltvP": "IPTV sağlayıcıları ekranından <strong>+ XMLTV Yönet</strong> seçeneğini belirleyerek hane genelinde kullanılacak 3 adede kadar ek XMLTV listesi ekleyebilir, EPG kaynak durumunu görebilir veya tüm rehberleri şimdi yenileyebilirsiniz. Listeler telefonunuzdan QR koduyla da eklenebilir.",
    "m.fs.restoreH": "Başka bir TV'den geri yükle",
    "m.fs.restoreP": "Kurulum sırasında: <strong>Geri Yükle</strong>'yi seçin ve Cloud Sync PIN'iniz ile Google hesabınızı girin.",
    "m.fs.restoreLink": "Kullanıcılar için Cloud Sync →",
