    "m.pr.up5_2": "Puanlamalar (👍/👎)",
    "m.pr.up5_3": "Filmler ve Diziler için göz atma filtreleri",
    "m.pr.up5_4": "IPTV kaynağı başına film ve dizi klasörü seçimi (yapılandırıldıysa)",
    "m.pr.up5_5": "Canlı TV klasörleri, favoriler ve rehber — veya birincil profilin TV kurulumunu paylaşma",
    "m.pr.kidsH": "Çocuk profili",
    "m.pr.kidsP": "Oluştururken <strong>Çocuk profili</strong> seçeneğini etkinleştirin. Kilitli içerikler ve PIN istemleri gizlenir.",
    "m.pr.kidsAlt": "Çocuk profili",
    "m.pr.pinH": "Ebeveyn denetimi PIN'i",
    "m.pr.pinP": "Ayarlar → Profil ve sistem → Ebeveyn denetimi PIN'i. Seçili içerikleri ve Canlı TV klasörlerini PIN gerektirecek şekilde kilitleyebilirsiniz.",
    "m.pr.liveH": "Profil başına Canlı TV",
    "m.pr.liveP": "Ek profillerde <strong>Birincil TV kurulumu</strong>'nu açabilirsiniz. Bu durumda o profil ilk profille aynı TV klasörlerini, favorileri, kanal sırasını ve rehber eşlemelerini kullanır. Klasörleri bağımsız seçmek için kapatın.",
    "m.pr.primaryH": "Birincil profil",
