    "m.ix.whatH": "ما هو SmartStream؟",
    "m.ix.whatP": "تطبيق لأجهزة Android TV و Fire TV يحوّل حساب IPTV الخاص بك إلى تجربة لغرفة المعيشة: أفلام ومسلسلات مع ملصقات، والبث المباشر مع دليل على الشاشة، ومتابعة المشاهدة، وملفات شخصية للعائلة، وبحث اختياري بالذكاء الاصطناعي. يمكن أن تحمل القنوات المفضلة بثوثًا احتياطية من مزوّدين آخرين، وينتقل التبديل الذكي بينها تلقائيًا عند تعثّر البث — وهي ميزة لا يقدّمها أي تطبيق IPTV آخر. تحتاج إلى مزوّد IPTV خاص بك — فـ SmartStream لا يبيع المحتوى.",
