    "m.du.homeH": "الرئيسية",
    "m.du.homeP": "الرئيسية هي العنصر الأول في القائمة اليسرى. تعرض ما كنت تشاهده، وما يقترحه التطبيق، والعناوين التي حفظتها.",
    "m.du.homeP2": "استخدم القائمة اليسرى لفتح البث المباشر أو الأفلام أو المسلسلات. وتوجد الإعدادات في أسفل القائمة نفسها.",
    "m.du.homeAlt": "الرئيسية",
