    "m.du.moviesTitle": "الاستخدام اليومي — الأفلام والمسلسلات — SmartStream",
    "m.du.moviesPageH": "3. الاستخدام اليومي — الأفلام والمسلسلات",
    "m.du.moviesLead": "تصفح الملصقات، وافتح التفاصيل، وقيّم العناوين، وابحث بالذكاء الاصطناعي. الأفلام والمسلسلات عنصران في القائمة بالأدوات نفسها.",
    "m.du.moviesH": "تصفّح",
