    "m.du.liveFs4": "<strong>OK</strong> — قائمة المشغّل (المعلومات، المسارات، تبديل البث إذا كان هناك عدة بثوث مرتبطة)",
    "m.du.liveFs5": "<strong>رجوع (Back)</strong> — العودة إلى الدليل (لا يغلق التطبيق)",
    "m.du.liveFsNote": "يمكن أن تحتفظ القنوات المفضلة بعدة بثوث من مزوّدين مختلفين. ينتقل التبديل الذكي تلقائيًا إلى بث احتياطي عندما يكون البث الحالي مشغولًا أو يتعطل — حصريًا في SmartStream.",
    "m.du.ratingsH": "التقييم",
    "m.du.ratingsP": "تعلّم التقييمات التطبيق ما تحبه. تستخدم صفوف الأفلام المقترحة والمسلسلات المقترحة في الرئيسية اختيارات الإعجاب/عدم الإعجاب مع مفتاح Gemini API.",
    "m.du.ratings1": "اضغط مطوّلًا على <strong>OK</strong> على بطاقة لـ 👍 / 👎",
    "m.du.ratings2": "أضف إلى قائمتي من شاشة التفاصيل",
    "m.du.ratings3": "التقييمات خاصة بكل ملف شخصي وتُزامن مع Cloud Sync",
