    "m.du.searchH": "البحث بالذكاء الاصطناعي",
    "m.du.searchP": "أيقونة البحث في الأفلام والمسلسلات، أو البحث الصوتي على Google TV إذا كان البحث الصوتي بالذكاء الاصطناعي مفعّلًا ضمن الإعدادات ← الواجهة واللغات ← الواجهة و OSD.",
    "m.du.searchP2": "يبحث التطبيق داخل مكتبتك الخاصة — وليس في الإنترنت كله. يمكنك الكتابة أو التحدث على Google TV.",
    "m.du.search1": "افتح أيقونة البحث في شاشة الأفلام أو المسلسلات.",
    "m.du.search2": "اسأل بلغة طبيعية، مثل “دراما جريمة من التسعينيات” أو “فيلم زومبي بكوميديا سوداء”.",
    "m.du.search3": "البحث الصوتي على Google TV: فعّله ضمن الإعدادات ← الواجهة واللغات ← الواجهة و OSD.",
    "m.du.search4": "يحتاج البحث بالذكاء الاصطناعي إلى مفتاح Gemini API ضمن الإعدادات ← الحسابات والاتصالات ← Gemini AI.",
