    "m.du.switchPageH": "3. الاستخدام اليومي — التبديل الذكي للبث",
    "m.du.switchLead": "التبديل الذكي بين المزوّدين: عندما يفشل التشغيل أو يأخذ جهاز آخر المنفذ، يبدّل SmartStream تلقائيًا. لا يوجد تطبيق IPTV آخر يفعل ذلك.",
    "m.du.switchWhatH": "ما الذي يفعله؟",
    "m.du.switchP": "تتوقف معظم تطبيقات IPTV عندما يتعطل البث أو عندما يستخدم تلفاز آخر في المنزل منفذ الدخول نفسه. يبحث SmartStream عن بث آخر ربطته بالفعل — من مزوّد آخر إذا لزم الأمر — ويواصل التشغيل.",
    "m.du.switchLi1": "<strong>البث المباشر:</strong> بثوث احتياطية مرفقة بقناة مفضلة.",
    "m.du.switchLi2": "<strong>الأفلام والمسلسلات:</strong> نسخة أخرى من العنوان نفسه لدى مزوّد ثانٍ.",
    "m.du.switchLi3": "<strong>المنفذ مشغول:</strong> إذا كان جهاز آخر يستخدم مزوّدًا، يمكن لـ SmartStream أن يطلب من ذلك التلفاز تحريره، ثم يبدّل.",
    "m.du.switchHowH": "كيفية إعداده",
