    "m.du.switchHow4": "فعّل التبديل الذكي ضمن الإعدادات ← التشغيل والبث المباشر ← المشغّل والشبكة.",
    "m.du.switchSetP": "لا يزال بإمكانك تبديل البثوث يدويًا من قائمة المشغّل (OK أثناء التشغيل).",
