    "m.st.accountAlt": "الحسابات والاتصالات",
    "m.st.account1": "<strong>مزوّدو IPTV</strong> — أضف ما يصل إلى 5 حسابات Xtream (عبر QR من الهاتف أو بالكتابة على التلفاز). لكل مزوّد: اختبار، حفظ، اختيار الأفلام والمسلسلات، اختيار قنوات التلفاز، الحد الأقصى للاتصالات، وتفعيل/تعطيل التشغيل لهذا الملف الشخصي.",
    "m.st.accountXmltv": "<strong>+ إدارة XMLTV</strong> (على شاشة المزوّد) — حالة مصدر EPG، وتحديث جميع الأدلة الآن، وما يصل إلى 3 قوائم XMLTV مخصصة مشتركة للعائلة بأكملها.",
