    "m.st.pnH": "المشغّل والشبكة",
    "m.st.pn1": "<strong>حجم مخزن الشبكة المؤقت</strong> — من صغير إلى كبير جدًا. الأكبر أكثر استقرارًا على الشبكات البطيئة؛ والأصغر يبدأ أسرع.",
    "m.st.pn2": "<strong>التبديل التلقائي للبث الضعيف</strong> — يخفي بثوث أفلام 4K H.264 في التفاصيل (غالبًا ما تتقطع). لا يتأثر Dolby Vision و HEVC/H.265. كما يبدّل تلقائيًا ترميزات 30 fps telecine.",
    "m.st.pn3": "<strong>التبديل الذكي</strong> — تجربة بث آخر تلقائيًا عند فشل التشغيل.",
    "m.st.pn4": "<strong>جودة البث المفضلة</strong> — تضع الجودة التي تختارها أولًا في قائمة التشغيل بالضغط المطوّل (مثل 4K UHD).",
    "m.st.liveH": "البث المباشر و EPG",
