    "m.st.live1": "<strong>التشغيل التلقائي لآخر قناة</strong> — عند تشغيل التطبيق، يفتح البث المباشر على آخر قناة شاهدتها.",
    "m.st.live2": "<strong>EPG ودليل البرامج</strong> — أيام EPG للأمام/للخلف، وقت التذكير المسبق للبرنامج، <strong>مطابقة قنوات EPG</strong> (مطابقة القنوات تلقائيًا مع أفضل مصدر XMLTV)، و<strong>EPG خارجي والتحديث</strong> (إضافة ما يصل إلى 3 قوائم XMLTV مخصصة وفرض تحديث الدليل).",
    "m.st.liveIcon": "<strong>مطابقة أيقونات القنوات</strong> — مطابقة شعارات القنوات تلقائيًا أو البحث عنها أو تخصيصها لمجلداتك.",
