    "m.st.live3": "يفتح خيارات إضافية للبث المباشر:",
    "m.st.live3a": "<strong>الشريط الجانبي لـ EPG</strong> — جميع مجلدات التلفاز، أو القنوات المفضلة (يخفي مجلدات المزوّد العادية ويفتح مباشرةً على المفضلة).",
