    "m.st.osTr1": "<strong>الإعدادات ← الواجهة واللغات ← الترجمة ← إعداد OpenSubtitles</strong> وسجّل الدخول بحسابك في OpenSubtitles (ميزة Pro).",
    "m.st.osTr2": "<strong>لغة الترجمة المفضلة</strong>: اختر اللغة التي تريد قراءتها. لا تعمل الترجمة التلقائية عند ضبطها على «بلا» أو «الإنجليزية».",
    "m.st.osTr3": "أضف مفتاح Gemini الخاص بك في <strong>الإعدادات ← الذكاء الاصطناعي</strong> (مفتاح مجاني من Google AI Studio). تستخدم الترجمة مفتاحك الخاص.",
    "m.st.osTr4": "بالعودة إلى صفحة OpenSubtitles، اضبط <strong>ترجمة OpenSubtitles</strong> على <strong>مفعّل</strong>. تكون متوقفة افتراضيًا وتُضبط لكل ملف شخصي.",
    "m.st.osUseH": "أثناء المشاهدة",
    "m.st.osUse1": "شغّل فيلمًا أو حلقة من صفحة التفاصيل. إذا لم تتوفر لغتك في البث ولا في OpenSubtitles، يختار SmartStream ملفًا باللغة الإنجليزية (أو ملفًا بأي لغة أخرى إذا لم تتوفر الإنجليزية) ويترجمه.",
    "m.st.osUse2": "تظهر عجلة تقدّم لفترة وجيزة. يبدأ الفيلم فور ترجمة الجزء الأول، وتُترجم بقية الأجزاء أثناء المشاهدة.",
    "m.st.osUse3": "يُحفظ الملف المترجم، لذا يبدأ في المرة القادمة فورًا. كما يعمل عند البث إلى جهاز آخر (Cast) ومن «متابعة المشاهدة».",
    "m.st.osUse4": "لاختيار ملف بنفسك، اضغط OK في المشغّل، ثم <strong>الترجمة ← OpenSubs</strong>، وابحث بأي لغة. عند تشغيل الإعداد، تُترجم الملفات باللغات الأخرى تلقائيًا؛ وعند إيقافه، ضع علامة على <strong>ترجمة اللغات الأخرى إلى …</strong>.",
    "m.st.osUse5": "يعرض سطر المعلومات في قائمة OK الملف النشط، على سبيل المثال <em>الدنماركية (Opensubs، مترجمة)</em>.",
    "m.st.osSyncH": "المزامنة التلقائية",
    "m.st.osSync1": "عند تشغيل ملف OpenSubtitles، يتحقق SmartStream من توقيته في الخلفية. إذا كان للفيلم مسار ترجمة خاص به فإنه يقارن وقت ظهور النص؛ وإلا فإنه يستمع إلى وقت تحدث الأشخاص.",
    "m.st.osSync2": "تظهر الترجمات كالمعتاد. وإذا كانت غير متزامنة، يقفز النص إلى موضعه الصحيح عادةً خلال دقيقة، ثم يُضبط بدقة خلال الدقائق القليلة التالية. قد يستغرق الفيلم الذي يبدأ بمقدمة موسيقية طويلة وقتًا أطول قليلًا.",
    "m.st.osSync3": "يُحفظ التصحيح لكل ملف ترجمة ويتبع أجهزتك الأخرى عبر Cloud Sync، لذا لن تنتظر إلا في المرة الأولى فقط.",
    "m.st.osSync4": "يمكنك دائمًا الضبط يدويًا باستخدام أزرار <strong>تأخير الترجمة − / +</strong> في قائمة OK. وإذا تعذّر على التطبيق العثور على التوقيت، يخبرك تلميح موجز بفعل ذلك.",
    "m.st.osNote": "تحتاج الترجمة إلى مفتاح Gemini. للمفتاح المجاني حد يومي؛ وإذا تم بلوغه سترى النص الأصلي، وتُترجم البقية في المرة القادمة.",
    "m.st.osdH": "الواجهة و OSD",
    "m.st.osd1": "<strong>مهلة الإخفاء التلقائي لشريط التشغيل</strong> — المدة التي يبقى فيها شريط التحكم ظاهرًا (أو إيقاف).",
    "m.st.osd2": "<strong>إظهار طبقة الشبكة</strong> — شبكة على الشاشة أثناء التصفح.",
    "m.st.osd3": "<strong>البحث الصوتي بالذكاء الاصطناعي</strong> — إظهار الميكروفون في البحث للاستعلامات باللغة الطبيعية (يتطلب Gemini).",
    "m.st.metaH": "اللغات والبيانات الوصفية",
    "m.st.meta1": "<strong>ترجمة الواجهة</strong> — لغة واجهة التطبيق.",
    "m.st.meta2": "<strong>لغة البيانات الوصفية (TMDB)</strong> — لغة العناوين والأوصاف من TMDB (الملف الرئيسي).",
    "m.st.sysH": "الملف الشخصي والنظام",
    "m.st.sysAlt": "الملف الشخصي والنظام",
    "m.st.sys1": "<strong>رمز PIN للرقابة الأبوية</strong> — إنشاء رمز PIN الذي يقفل المحتوى والمجلدات المحددة أو تغييره أو إزالته (مخفي في ملفات الأطفال).",
    "m.st.sys2": "<strong>تقييمات الملف الشخصي</strong> — مراجعة 👍 / 👎 أو إزالتها لهذا الملف الشخصي.",
    "m.st.sys3": "<strong>التشخيص وحل المشكلات</strong> — حالة النظام والمزوّد، وطبقة الأداء، و<strong>إرسال السجلات عبر QR</strong> للدعم.",
    "m.st.ratingsAlt": "تقييمات الملف الشخصي",
    "m.st.pagerPrev": "← الملفات الشخصية",
