    "m.tr.p6a": "افتح مزوّدي IPTV ← اختيار قنوات التلفاز واحفظ مجلدًا واحدًا على الأقل",
    "m.tr.p6b": "في الملفات الإضافية، تحقق مما إذا كان «إعداد التلفاز الرئيسي» مفعّلًا أم متوقفًا",
