    "m.tr.p2c": "البث المباشر: إذا كان جهاز آخر يستخدم تسجيل الدخول نفسه لـ IPTV، يمكن للقنوات المفضلة المرتبطة ببثوث احتياطية التبديل تلقائيًا",
